PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <http://w3id.org/bricks/ref#>
SELECT ?tz ?tsid ?set ?setid WHERE {
  ?z a brick:Zone ; brick:hasSubclass brick:Zone ; rdfs:label "Core_top" .
  ?tz ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?set [ rdfs:label "Core_top cooling setpoint" ] ref:hasTimeseriesId ?setid . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX brick: <http://brickschema.org/schema/Brick#>
SELECT ?s ?p ?o WHERE {
  ?s rdfs:label ?l .
  FILTER (?l LIKE "%Core%")
}

PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?l WHERE {
  ?s rdfs:label ?l .
